namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string CourseCode { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be 2 uppercase letters followed by 6 digits (e.g., CS123456).")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    Task<List<Department>> GetDepartmentsAsync();
    Task<Department?> GetDepartmentAsync(int id);
    Task<List<Course>> GetCoursesAsync(string? searchTerm = null, int? departmentId = null);
    Task<List<Course>> GetFeaturedCoursesAsync();
    Task<Course?> GetCourseAsync(int id);
    Task<bool> SubmitEnrollmentRequestAsync(EnrollmentRequest request);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private static readonly List<Department> Departments =
    [
        new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
        new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and critical analysis." },
        new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and their impact on the present." },
    ];

    private static readonly List<Course> Courses =
    [
        new() { Id = 1, Title = "Introduction to Programming", CourseCode = "CS101", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses and has authored two textbooks on Python programming.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
        new() { Id = 2, Title = "Data Structures & Algorithms", CourseCode = "CS201", Description = "Study of fundamental data structures (linked lists, trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms).", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", InstructorName = "Dr. Michael Torres", InstructorBio = "Dr. Torres is a former software engineer at a major tech company with research interests in algorithm optimization.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
        new() { Id = 3, Title = "Database Systems", CourseCode = "CS340", Description = "Design and implementation of relational database systems. Covers SQL, normalization, indexing, transactions, and an introduction to NoSQL databases.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Lisa Park", InstructorBio = "Dr. Park spent a decade in industry working on distributed database systems before joining academia.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false },
        new() { Id = 4, Title = "Calculus I", CourseCode = "MATH101", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator known for making calculus accessible to all students.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true },
        new() { Id = 5, Title = "Linear Algebra", CourseCode = "MATH220", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications to data science and machine learning.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Anna Petrov", InstructorBio = "Dr. Petrov's research focuses on computational linear algebra and its applications in machine learning.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
        new() { Id = 6, Title = "Classical Mechanics", CourseCode = "PHYS201", Description = "Newtonian mechanics, conservation laws, oscillations, and an introduction to Lagrangian mechanics.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. James Wright", InstructorBio = "Dr. Wright is a theoretical physicist with over 20 years of teaching experience.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false },
        new() { Id = 7, Title = "Quantum Physics", CourseCode = "PHYS310", Description = "Introduction to quantum mechanics: wave-particle duality, Schrödinger equation, hydrogen atom, and spin.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. Emily Nakamura", InstructorBio = "Dr. Nakamura's research in quantum information theory has been published in leading physics journals.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = true },
        new() { Id = 8, Title = "Creative Writing", CourseCode = "ENG210", Description = "Workshop-based course covering fiction, poetry, and creative nonfiction. Students develop a portfolio of original work.", Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", InstructorName = "Prof. David Okafor", InstructorBio = "Prof. Okafor is a published novelist and poet whose work has appeared in major literary journals.", DepartmentId = 4, DepartmentName = "English", IsFeatured = false },
        new() { Id = 9, Title = "American Literature", CourseCode = "ENG320", Description = "Survey of American literary works from the colonial period to the present, examining themes of identity, freedom, and democracy.", Credits = 3, Schedule = "Mon/Wed 10:00–11:15 AM", InstructorName = "Dr. Maria Gonzalez", InstructorBio = "Dr. Gonzalez specializes in 20th-century American literature with a focus on multicultural voices.", DepartmentId = 4, DepartmentName = "English", IsFeatured = false },
        new() { Id = 10, Title = "World History: 1500–Present", CourseCode = "HIST150", Description = "A global survey of major historical developments from the Age of Exploration through the modern era.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Thomas Reed", InstructorBio = "Dr. Reed is a historian specializing in comparative world history and has led study-abroad programs on three continents.", DepartmentId = 5, DepartmentName = "History", IsFeatured = true },
    ];

    public Task<List<Department>> GetDepartmentsAsync()
    {
        return Task.FromResult(Departments.ToList());
    }

    public Task<Department?> GetDepartmentAsync(int id)
    {
        return Task.FromResult(Departments.FirstOrDefault(d => d.Id == id));
    }

    public Task<List<Course>> GetCoursesAsync(string? searchTerm = null, int? departmentId = null)
    {
        var query = Courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        if (departmentId.HasValue)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        return Task.FromResult(query.ToList());
    }

    public Task<List<Course>> GetFeaturedCoursesAsync()
    {
        return Task.FromResult(Courses.Where(c => c.IsFeatured).ToList());
    }

    public Task<Course?> GetCourseAsync(int id)
    {
        return Task.FromResult(Courses.FirstOrDefault(c => c.Id == id));
    }

    public Task<bool> SubmitEnrollmentRequestAsync(EnrollmentRequest request)
    {
        // In production, this would persist to a database
        return Task.FromResult(true);
    }
}

