arguments.file_text:
@page "/"
@inject UniversityCourseCatalog.Services.ICatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<h1>University Course Catalog</h1>
<p class="lead">Welcome to the university course catalog. Browse our departments, explore courses, and submit enrollment requests.</p>

<h2>Featured Courses</h2>
<div class="row">
    @if (featuredCourses is not null)
    {
        @foreach (var course in featuredCourses)
        {
            <div class="col-md-6 col-lg-4 mb-4">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@course.CourseCode — @course.Title</h5>
                        <p class="card-text text-muted">@course.DepartmentName · @course.Credits credits</p>
                        <p class="card-text">@Truncate(course.Description, 100)</p>
                    </div>
                    <div class="card-footer">
                        <a href="courses/@course.Id" class="btn btn-primary btn-sm">View Details</a>
                    </div>
                </div>
            </div>
        }
    }
</div>

<h2 class="mt-4">Departments</h2>
<div class="row">
    @if (departments is not null)
    {
        @foreach (var dept in departments)
        {
            <div class="col-md-6 col-lg-4 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@dept.Name</h5>
                        <p class="card-text">@dept.Description</p>
                        <a href="courses?departmentId=@dept.Id" class="btn btn-outline-primary btn-sm">Browse @dept.Code Courses</a>
                    </div>
                </div>
            </div>
        }
    }
</div>

@code {
    private List<UniversityCourseCatalog.Models.Course>? featuredCourses;
    private List<UniversityCourseCatalog.Models.Department>? departments;

    protected override async Task OnInitializedAsync()
    {
        featuredCourses = await CatalogService.GetFeaturedCoursesAsync();
        departments = await CatalogService.GetDepartmentsAsync();
    }

    private static string Truncate(string text, int maxLength)
    {
        if (text.Length <= maxLength) return text;
        return text[..maxLength] + "…";
    }
}

@page "/courses"
@rendermode InteractiveServer
@inject UniversityCourseCatalog.Services.ICatalogService CatalogService

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <input type="text" class="form-control" placeholder="Search by title, code, or instructor…"
               @bind="searchTerm" @bind:event="oninput" @bind:after="FilterCourses" />
    </div>
    <div class="col-md-4">
        <select class="form-select" @bind="selectedDepartmentId" @bind:after="FilterCourses">
            <option value="0">All Departments</option>
            @if (departments is not null)
            {
                @foreach (var dept in departments)
                {
                    <option value="@dept.Id">@dept.Name</option>
                }
            }
        </select>
    </div>
</div>

@if (courses is null)
{
    <p><em>Loading courses…</em></p>
}
else if (courses.Count == 0)
{
    <p>No courses match your search criteria.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Instructor</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in courses)
                {
                    <tr>
                        <td>@course.CourseCode</td>
                        <td>@course.Title</td>
                        <td>@course.DepartmentName</td>
                        <td>@course.Credits</td>
                        <td>@course.InstructorName</td>
                        <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<UniversityCourseCatalog.Models.Course>? courses;
    private List<UniversityCourseCatalog.Models.Department>? departments;
    private string searchTerm = string.Empty;
    private int selectedDepartmentId;

    protected override async Task OnInitializedAsync()
    {
        departments = await CatalogService.GetDepartmentsAsync();
        await FilterCourses();
    }

    private async Task FilterCourses()
    {
        int? deptFilter = selectedDepartmentId > 0 ? selectedDepartmentId : null;
        courses = await CatalogService.GetCoursesAsync(searchTerm, deptFilter);
    }
}

@page "/courses/{Id:int}"
@inject UniversityCourseCatalog.Services.ICatalogService CatalogService

<PageTitle>@(course?.Title ?? "Course Details")</PageTitle>

@if (course is null)
{
    <p><em>Loading course…</em></p>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            <li class="breadcrumb-item active" aria-current="page">@course.CourseCode</li>
        </ol>
    </nav>

    <h1>@course.CourseCode — @course.Title</h1>

    <div class="row mt-4">
        <div class="col-md-8">
            <h2>Description</h2>
            <p>@course.Description</p>

            <h2>Schedule</h2>
            <p>@course.Schedule</p>

            <h2>Instructor</h2>
            <h5>@course.InstructorName</h5>
            <p>@course.InstructorBio</p>
        </div>
        <div class="col-md-4">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Course Info</h5>
                    <ul class="list-unstyled">
                        <li><strong>Code:</strong> @course.CourseCode</li>
                        <li><strong>Credits:</strong> @course.Credits</li>
                        <li><strong>Department:</strong> @course.DepartmentName</li>
                    </ul>
                    <a href="enroll?courseId=@course.Id" class="btn btn-success w-100">Request Enrollment</a>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private UniversityCourseCatalog.Models.Course? course;

    protected override async Task OnInitializedAsync()
    {
        course = await CatalogService.GetCourseAsync(Id);
    }
}

@page "/enroll"
@inject UniversityCourseCatalog.Services.ICatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p>Fill out the form below to submit an enrollment request.</p>

@if (submitted)
{
    <div class="alert alert-success" role="alert">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Your enrollment request has been submitted successfully. You will receive a confirmation via your student email.</p>
        <hr />
        <a href="courses" class="btn btn-outline-primary">Browse More Courses</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-md-8 col-lg-6">
            <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="enrollment">
                <DataAnnotationsValidator />
                <AntiforgeryToken />
                <ValidationSummary class="text-danger" />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <InputText id="studentName" class="form-control" @bind-Value="model.StudentName" />
                    <ValidationMessage For="() => model.StudentName" class="text-danger" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <InputText id="studentId" class="form-control" @bind-Value="model.StudentId" placeholder="e.g., CS123456" />
                    <ValidationMessage For="() => model.StudentId" class="text-danger" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <InputSelect id="courseId" class="form-select" @bind-Value="model.CourseId">
                        <option value="0">— Select a course —</option>
                        @if (courses is not null)
                        {
                            @foreach (var course in courses)
                            {
                                <option value="@course.Id">@course.CourseCode — @course.Title</option>
                            }
                        }
                    </InputSelect>
                    <ValidationMessage For="() => model.CourseId" class="text-danger" />
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
            </EditForm>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    private UniversityCourseCatalog.Models.EnrollmentRequest model { get; set; } = new();

    [SupplyParameterFromQuery]
    private int? CourseId { get; set; }

    private List<UniversityCourseCatalog.Models.Course>? courses;
    private bool submitted;

    protected override async Task OnInitializedAsync()
    {
        courses = await CatalogService.GetCoursesAsync();

        if (CourseId.HasValue && model.CourseId == 0)
        {
            model.CourseId = CourseId.Value;
        }
    }

    private async Task HandleSubmit()
    {
        await CatalogService.SubmitEnrollmentRequestAsync(model);
        submitted = true;
    }
}

@page "/"
@inject UniversityCourseCatalog.Services.ICatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<h1>University Course Catalog</h1>
<p class="lead">Welcome to the university course catalog. Browse our departments, explore courses, and submit enrollment requests.</p>

<h2>Featured Courses</h2>
<div class="row">
    @if (featuredCourses is not null)
    {
        @foreach (var course in featuredCourses)
        {
            <div class="col-md-6 col-lg-4 mb-4">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@course.CourseCode — @course.Title</h5>
                        <p class="card-text text-muted">@course.DepartmentName · @course.Credits credits</p>
                        <p class="card-text">@Truncate(course.Description, 100)</p>
                    </div>
                    <div class="card-footer">
                        <a href="courses/@course.Id" class="btn btn-primary btn-sm">View Details</a>
                    </div>
                </div>
            </div>
        }
    }
</div>

<h2 class="mt-4">Departments</h2>
<div class="row">
    @if (departments is not null)
    {
        @foreach (var dept in departments)
        {
            <div class="col-md-6 col-lg-4 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@dept.Name</h5>
                        <p class="card-text">@dept.Description</p>
                        <a href="courses?departmentId=@dept.Id" class="btn btn-outline-primary btn-sm">Browse @dept.Code Courses</a>
                    </div>
                </div>
            </div>
        }
    }
</div>

@code {
    private List<UniversityCourseCatalog.Models.Course>? featuredCourses;
    private List<UniversityCourseCatalog.Models.Department>? departments;

    protected override async Task OnInitializedAsync()
    {
        featuredCourses = await CatalogService.GetFeaturedCoursesAsync();
        departments = await CatalogService.GetDepartmentsAsync();
    }

    private static string Truncate(string text, int maxLength)
    {
        if (text.Length <= maxLength) return text;
        return text[..maxLength] + "…";
    }
}

@page "/courses"
@rendermode InteractiveServer
@inject UniversityCourseCatalog.Services.ICatalogService CatalogService

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <input type="text" class="form-control" placeholder="Search by title, code, or instructor…"
               @bind="searchTerm" @bind:event="oninput" @bind:after="FilterCourses" />
    </div>
    <div class="col-md-4">
        <select class="form-select" @bind="selectedDepartmentId" @bind:after="FilterCourses">
            <option value="0">All Departments</option>
            @if (departments is not null)
            {
                @foreach (var dept in departments)
                {
                    <option value="@dept.Id">@dept.Name</option>
                }
            }
        </select>
    </div>
</div>

@if (courses is null)
{
    <p><em>Loading courses…</em></p>
}
else if (courses.Count == 0)
{
    <p>No courses match your search criteria.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Instructor</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in courses)
                {
                    <tr>
                        <td>@course.CourseCode</td>
                        <td>@course.Title</td>
                        <td>@course.DepartmentName</td>
                        <td>@course.Credits</td>
                        <td>@course.InstructorName</td>
                        <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<UniversityCourseCatalog.Models.Course>? courses;
    private List<UniversityCourseCatalog.Models.Department>? departments;
    private string searchTerm = string.Empty;
    private int selectedDepartmentId;

    protected override async Task OnInitializedAsync()
    {
        departments = await CatalogService.GetDepartmentsAsync();
        await FilterCourses();
    }

    private async Task FilterCourses()
    {
        int? deptFilter = selectedDepartmentId > 0 ? selectedDepartmentId : null;
        courses = await CatalogService.GetCoursesAsync(searchTerm, deptFilter);
    }
}

